const e=JSON.parse('{"key":"v-0d6e5b16","path":"/ai-dev/AgentScope/06.HarnessAgent%EF%BC%9A%E4%B8%BA%20ReActAgent%20%E8%A3%85%E4%B8%8A%E6%93%8D%E4%BD%9C%E7%B3%BB%E7%BB%9F.html","title":"6.HarnessAgent：为 ReActAgent 装上操作系统","lang":"zh-CN","frontmatter":{"order":6,"title":"6.HarnessAgent：为 ReActAgent 装上操作系统","tag":["AgentScope","Java","HarnessAgent","AI Agent"],"category":["AgentScope Java新手村","进阶架构","HarnessAgent 工程底座"],"date":"2026-07-30T08:00:00.000Z","keywords":"AgentScope Java 2.0 HarnessAgent ReActAgent 操作系统 进程管理 Session 子Agent编排 沙箱隔离 文件系统 Workspace Middleware","description":"ReActAgent 是一颗纯粹的 CPU——只懂\\"取指→译码→执行\\"的无限循环。但单靠 CPU 跑不了任何业务程序，它需要操作系统来管理进程、调度内存、隔离文件。HarnessAgent 就是 ReActAgent 的操作系统内核。 HarnessAgent：为 ReActAgent 装上操作系统——从 CPU 到操作系统，Harness 的四大子系统深度解析 在上一篇文章中，我们掌握了让 Agent 直接返回 Java 对象的技巧，体验了 ReActAgent 在结构化输出上的便利。但不知道各位小伙伴有没有注意到一个关键细节——我们所有的 Demo，无论使用 ReActAgent 还是 HarnessAgent，call() 方法都需要传入一个 RuntimeContext。 那么问题来了——为什么？因为 ReActAgent 是无状态的。它像 CPU 一样不保存任何进程上下文，每次执行只关心当前输入的指令。同一个 ReActAgent 实例可以同时为 Alice 和 Bob 服务，互不干扰，因为它根本不\\"记住\\"任何东西——所有状态都通过 RuntimeContext 外置，随着 Reactor 上下文在调用链中传递。 这种设计优雅、高效，但现实世界的 Agent 应用，需要的远不止一个\\"取指→译码→执行\\"的循环。它还需要： 进程管理：多个用户同时使用，状态不能串；会话中断后能原地恢复 文件系统：Agent 需要读写文件、保存中间产物，不同用户之间相互隔离 内存管理：对话长了会爆 Token，需要自动压缩和交换（Swap） 安全隔离：Agent 执行的代码不能直接操作宿主机，必须扔进\\"容器\\"里 进程间通信（IPC）：一个 Agent 需要委派子任务给其他专门的 Agent 这些正是操作系统要解决的核心问题——而 HarnessAgent，就是 Agent 世界的操作系统内核。它不是一个新的推理引擎，而是在 ReActAgent 这个\\"CPU\\"外面包裹了一层工程化的操作系统内核。","head":[["meta",{"property":"og:url","content":"https://ppai.top/ai-guides/ai-dev/AgentScope/06.HarnessAgent%EF%BC%9A%E4%B8%BA%20ReActAgent%20%E8%A3%85%E4%B8%8A%E6%93%8D%E4%BD%9C%E7%B3%BB%E7%BB%9F.html"}],["meta",{"property":"og:site_name","content":"Helllo LLM Guides"}],["meta",{"property":"og:title","content":"6.HarnessAgent：为 ReActAgent 装上操作系统"}],["meta",{"property":"og:description","content":"ReActAgent 是一颗纯粹的 CPU——只懂\\"取指→译码→执行\\"的无限循环。但单靠 CPU 跑不了任何业务程序，它需要操作系统来管理进程、调度内存、隔离文件。HarnessAgent 就是 ReActAgent 的操作系统内核。 HarnessAgent：为 ReActAgent 装上操作系统——从 CPU 到操作系统，Harness 的四大子系统深度解析 在上一篇文章中，我们掌握了让 Agent 直接返回 Java 对象的技巧，体验了 ReActAgent 在结构化输出上的便利。但不知道各位小伙伴有没有注意到一个关键细节——我们所有的 Demo，无论使用 ReActAgent 还是 HarnessAgent，call() 方法都需要传入一个 RuntimeContext。 那么问题来了——为什么？因为 ReActAgent 是无状态的。它像 CPU 一样不保存任何进程上下文，每次执行只关心当前输入的指令。同一个 ReActAgent 实例可以同时为 Alice 和 Bob 服务，互不干扰，因为它根本不\\"记住\\"任何东西——所有状态都通过 RuntimeContext 外置，随着 Reactor 上下文在调用链中传递。 这种设计优雅、高效，但现实世界的 Agent 应用，需要的远不止一个\\"取指→译码→执行\\"的循环。它还需要： 进程管理：多个用户同时使用，状态不能串；会话中断后能原地恢复 文件系统：Agent 需要读写文件、保存中间产物，不同用户之间相互隔离 内存管理：对话长了会爆 Token，需要自动压缩和交换（Swap） 安全隔离：Agent 执行的代码不能直接操作宿主机，必须扔进\\"容器\\"里 进程间通信（IPC）：一个 Agent 需要委派子任务给其他专门的 Agent 这些正是操作系统要解决的核心问题——而 HarnessAgent，就是 Agent 世界的操作系统内核。它不是一个新的推理引擎，而是在 ReActAgent 这个\\"CPU\\"外面包裹了一层工程化的操作系统内核。"}],["meta",{"property":"og:type","content":"article"}],["meta",{"property":"og:locale","content":"zh-CN"}],["meta",{"property":"og:updated_time","content":"2026-08-07T09:39:42.000Z"}],["meta",{"property":"article:tag","content":"AgentScope"}],["meta",{"property":"article:tag","content":"Java"}],["meta",{"property":"article:tag","content":"HarnessAgent"}],["meta",{"property":"article:tag","content":"AI Agent"}],["meta",{"property":"article:published_time","content":"2026-07-30T08:00:00.000Z"}],["meta",{"property":"article:modified_time","content":"2026-08-07T09:39:42.000Z"}],["script",{"type":"application/ld+json"},"{\\"@context\\":\\"https://schema.org\\",\\"@type\\":\\"Article\\",\\"headline\\":\\"6.HarnessAgent：为 ReActAgent 装上操作系统\\",\\"image\\":[\\"\\"],\\"datePublished\\":\\"2026-07-30T08:00:00.000Z\\",\\"dateModified\\":\\"2026-08-07T09:39:42.000Z\\",\\"author\\":[]}"]]},"headers":[{"level":2,"title":"一、从 CPU 到操作系统：为什么要分层？","slug":"一、从-cpu-到操作系统-为什么要分层","link":"#一、从-cpu-到操作系统-为什么要分层","children":[{"level":3,"title":"1. 现状回顾：无状态的 ReActAgent","slug":"_1-现状回顾-无状态的-reactagent","link":"#_1-现状回顾-无状态的-reactagent","children":[]},{"level":3,"title":"2. 痛点提炼：裸 CPU 无法直接跑业务","slug":"_2-痛点提炼-裸-cpu-无法直接跑业务","link":"#_2-痛点提炼-裸-cpu-无法直接跑业务","children":[]},{"level":3,"title":"3. 设计哲学：微内核架构（薄包装）","slug":"_3-设计哲学-微内核架构-薄包装","link":"#_3-设计哲学-微内核架构-薄包装","children":[]}]},{"level":2,"title":"二、进程管理（Session）：让 Agent 状态像进程一样可恢复","slug":"二、进程管理-session-让-agent-状态像进程一样可恢复","link":"#二、进程管理-session-让-agent-状态像进程一样可恢复","children":[{"level":3,"title":"1. 从临时 Context 到持久化 PCB","slug":"_1-从临时-context-到持久化-pcb","link":"#_1-从临时-context-到持久化-pcb","children":[]},{"level":3,"title":"2. 进程快照与热迁移（自动恢复）","slug":"_2-进程快照与热迁移-自动恢复","link":"#_2-进程快照与热迁移-自动恢复","children":[]},{"level":3,"title":"3. 分时复用与多租户隔离","slug":"_3-分时复用与多租户隔离","link":"#_3-分时复用与多租户隔离","children":[]}]},{"level":2,"title":"三、文件系统与内存管理：Workspace 与 Memory Compaction","slug":"三、文件系统与内存管理-workspace-与-memory-compaction","link":"#三、文件系统与内存管理-workspace-与-memory-compaction","children":[{"level":3,"title":"1. Workspace：Agent 的持久化根目录","slug":"_1-workspace-agent-的持久化根目录","link":"#_1-workspace-agent-的持久化根目录","children":[]},{"level":3,"title":"2. Memory Compaction：内存压缩与交换（Swap）","slug":"_2-memory-compaction-内存压缩与交换-swap","link":"#_2-memory-compaction-内存压缩与交换-swap","children":[]}]},{"level":2,"title":"四、进程间通信（Subagent）：实现 Agent 的 fork() 系统调用","slug":"四、进程间通信-subagent-实现-agent-的-fork-系统调用","link":"#四、进程间通信-subagent-实现-agent-的-fork-系统调用","children":[{"level":3,"title":"1. 声明式配置：像 systemd 一样定义子服务","slug":"_1-声明式配置-像-systemd-一样定义子服务","link":"#_1-声明式配置-像-systemd-一样定义子服务","children":[]},{"level":3,"title":"2. 编程式 Fork","slug":"_2-编程式-fork","link":"#_2-编程式-fork","children":[]},{"level":3,"title":"3. 通信模式：独立地址空间 vs 共享内存","slug":"_3-通信模式-独立地址空间-vs-共享内存","link":"#_3-通信模式-独立地址空间-vs-共享内存","children":[]}]},{"level":2,"title":"五、安全隔离（Sandbox）：用户态与内核态分离","slug":"五、安全隔离-sandbox-用户态与内核态分离","link":"#五、安全隔离-sandbox-用户态与内核态分离","children":[{"level":3,"title":"1. 容器化隔离（虚拟内存与命名空间）","slug":"_1-容器化隔离-虚拟内存与命名空间","link":"#_1-容器化隔离-虚拟内存与命名空间","children":[]},{"level":3,"title":"2. 隔离级别（权限 rings）","slug":"_2-隔离级别-权限-rings","link":"#_2-隔离级别-权限-rings","children":[]},{"level":3,"title":"3. 快照与休眠（Suspend to Disk）","slug":"_3-快照与休眠-suspend-to-disk","link":"#_3-快照与休眠-suspend-to-disk","children":[]},{"level":3,"title":"4. 生命周期管理（资源回收）","slug":"_4-生命周期管理-资源回收","link":"#_4-生命周期管理-资源回收","children":[]}]},{"level":2,"title":"六、Middleware 执行顺序：操作系统的初始化加载","slug":"六、middleware-执行顺序-操作系统的初始化加载","link":"#六、middleware-执行顺序-操作系统的初始化加载","children":[]},{"level":2,"title":"七、从单机到集群：三种部署场景一览","slug":"七、从单机到集群-三种部署场景一览","link":"#七、从单机到集群-三种部署场景一览","children":[{"level":3,"title":"场景一：本地开发环境（单机操作系统）","slug":"场景一-本地开发环境-单机操作系统","link":"#场景一-本地开发环境-单机操作系统","children":[]},{"level":3,"title":"场景二：SaaS 多租户（分时操作系统）","slug":"场景二-saas-多租户-分时操作系统","link":"#场景二-saas-多租户-分时操作系统","children":[]},{"level":3,"title":"场景三：企业级分布式集群（集群操作系统）","slug":"场景三-企业级分布式集群-集群操作系统","link":"#场景三-企业级分布式集群-集群操作系统","children":[]}]},{"level":2,"title":"八、小结","slug":"八、小结","link":"#八、小结","children":[]},{"level":2,"title":"九、其他","slug":"九、其他","link":"#九、其他","children":[{"level":3,"title":"0. 项目","slug":"_0-项目","link":"#_0-项目","children":[]},{"level":3,"title":"1. 下篇预告","slug":"_1-下篇预告","link":"#_1-下篇预告","children":[]}]}],"git":{"createdTime":1786095582000,"updatedTime":1786095582000,"contributors":[{"name":"yihui","email":"bangzewu@126.com","commits":1}]},"readingTime":{"minutes":17.91,"words":5372},"filePathRelative":"ai-dev/AgentScope/06.HarnessAgent：为 ReActAgent 装上操作系统.md","localizedDate":"2026年7月30日","excerpt":"<blockquote>\\n<p>ReActAgent 是一颗纯粹的 CPU——只懂\\"取指→译码→执行\\"的无限循环。但单靠 CPU 跑不了任何业务程序，它需要操作系统来管理进程、调度内存、隔离文件。<strong>HarnessAgent 就是 ReActAgent 的操作系统内核。</strong></p>\\n</blockquote>\\n<figure><img src=\\"https://imgbed.ppai.top/file/1785400561899_fa0WoiZwW.jpeg\\" alt=\\"\\" tabindex=\\"0\\" loading=\\"lazy\\"><figcaption></figcaption></figure>\\n<h1> HarnessAgent：为 ReActAgent 装上操作系统——从 CPU 到操作系统，Harness 的四大子系统深度解析</h1>\\n<p>在上一篇文章中，我们掌握了让 Agent 直接返回 Java 对象的技巧，体验了 ReActAgent 在结构化输出上的便利。但不知道各位小伙伴有没有注意到一个关键细节——我们所有的 Demo，无论使用 ReActAgent 还是 HarnessAgent，<code>call()</code> 方法都需要传入一个 <code>RuntimeContext</code>。</p>\\n<p>那么问题来了——为什么？因为 <strong>ReActAgent 是无状态的</strong>。它像 CPU 一样不保存任何进程上下文，每次执行只关心当前输入的指令。同一个 ReActAgent 实例可以同时为 Alice 和 Bob 服务，互不干扰，因为它根本不\\"记住\\"任何东西——所有状态都通过 <code>RuntimeContext</code> 外置，随着 Reactor 上下文在调用链中传递。</p>\\n<p>这种设计优雅、高效，但现实世界的 Agent 应用，需要的远不止一个\\"取指→译码→执行\\"的循环。它还需要：</p>\\n<ul>\\n<li><strong>进程管理</strong>：多个用户同时使用，状态不能串；会话中断后能原地恢复</li>\\n<li><strong>文件系统</strong>：Agent 需要读写文件、保存中间产物，不同用户之间相互隔离</li>\\n<li><strong>内存管理</strong>：对话长了会爆 Token，需要自动压缩和交换（Swap）</li>\\n<li><strong>安全隔离</strong>：Agent 执行的代码不能直接操作宿主机，必须扔进\\"容器\\"里</li>\\n<li><strong>进程间通信（IPC）</strong>：一个 Agent 需要委派子任务给其他专门的 Agent</li>\\n</ul>\\n<p>这些正是操作系统要解决的核心问题——而 HarnessAgent，就是 Agent 世界的操作系统内核。它不是一个新的推理引擎，而是在 ReActAgent 这个\\"CPU\\"外面包裹了一层工程化的操作系统内核。</p>\\n","copyright":{},"autoDesc":true}');export{e as data};
